    return f"({digits[:3]}) {digits[3:6]}-{digits[6:]}"

import re

_ALLOWED = re.compile(r"^\+?[\d\s().-]+$")


def normalize_phone(s):
    """Format a US phone number as '(XXX) XXX-XXXX'.

    Accepts common formats such as '(555) 123-4567', '555-123-4567',
    '555.123.4567', '5551234567', '1-555-123-4567', '+1 555 123 4567',
    and '+15551234567'. Raises ValueError for invalid numbers.
    """
    if not isinstance(s, str):
        raise ValueError(f"Phone number must be a string, got {type(s).__name__}")

    s = s.strip()
    if not s or not _ALLOWED.match(s):
        raise ValueError(f"Invalid phone number: {s!r}")

    if s.startswith("+"):
        if not s.startswith("+1"):
            raise ValueError(f"Only US (+1) numbers are supported: {s!r}")
        digits = s[1:]
        digits = re.sub(r"\D", "", digits)
        if len(digits) != 11 or digits[0] != "1":
            raise ValueError(f"Invalid phone number: {s!r}")
        digits = digits[1:]
    else:
        digits = re.sub(r"\D", "", s)
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]

    if len(digits) != 10:
        raise ValueError(f"US phone number must have 10 digits: {s!r}")

    area, exchange, line = digits[:3], digits[3:6], digits[6:]

    # NANP rules: area code and exchange must start with 2-9
    if area[0] in "01" or exchange[0] in "01":
        raise ValueError(f"Invalid US phone number: {s!r}")

    # Reject N11 area codes and exchanges (e.g., 911, 411) as not valid numbers
    if area[1:] == "11" or exchange[1:] == "11":
        raise ValueError(f"Invalid US phone number: {s!r}")

    return f"({area}) {exchange}-{line}"

def flatten(nested):
    """Flatten arbitrarily nested lists and tuples into a single flat list.

    Strings (and bytes) are treated as atomic values and kept whole.
    """
    result = []
    stack = [iter(nested)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, (list, tuple)):
            stack.append(iter(item))
        else:
            result.append(item)
    return result

