from typing import Dict, Union

def hole_check_scan_end(line: str, in_quotes: bool, escape: bool) -> None:
    """Called once after the scanner has consumed the whole line.

    Decide what happens when the line ends in an unsafe state.

    - in_quotes is True when the line ends inside an open double-quoted value.
      This must raise ValueError (the test suite requires it).
    - escape is True when the line ends with a dangling backslash inside
      quotes. The scanner reaches this only when in_quotes is also True, so
      the decision is already covered by in_quotes. Decide whether any other
      trailing-backslash case needs handling.

    Return None if the line is well formed. Raise ValueError if it is not.
    """
    raise NotImplementedError

def hole_split_pair(segment: str) -> tuple:
    """Split one already-trimmed, non-empty segment into (key, value).

    Return a 2-tuple (key, value) where:
    - For a bare key (no '=' in the segment), return (key, True).
    - For 'key=value', return (key, value) with both sides stripped of
      surrounding whitespace.
    - Decide how a double-quoted value is passed back. The caller
      does not unquote, so this function must return the final value
      (quotes removed, escapes resolved).

    Raise ValueError if the key is empty.
    """
    raise NotImplementedError

def _unquote(text: str) -> str:
    out = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == '\\' and i + 1 < len(text):
            out.append(text[i + 1])
            i += 2
        else:
            out.append(ch)
            i += 1
    return ''.join(out)

def parse_kv(line: str) -> Dict[str, Union[str, bool]]:
    """Parse a config line like 'a=1; debug; msg="hi; there"' into a dict.

    - Pairs are separated by semicolons. Semicolons inside double-quoted
      values do not split pairs.
    - 'key=value' maps to the string value.
    - A bare key (no '=') maps to True.
    - Double-quoted values have their quotes removed. Inside quotes, a
      backslash escapes the following character (e.g. \\" or \\\\).
    - Malformed input is reported by the hole_ functions.
    """
    segments = []
    current = []
    in_quotes = False
    escape = False
    for ch in line:
        if escape:
            current.append(ch)
            escape = False
        elif in_quotes and ch == '\\':
            current.append(ch)
            escape = True
        elif ch == '"':
            current.append(ch)
            in_quotes = not in_quotes
        elif ch == ';' and (not in_quotes):
            segments.append(''.join(current))
            current = []
        else:
            current.append(ch)
    segments.append(''.join(current))
    hole_check_scan_end(line, in_quotes, escape)
    result: Dict[str, Union[str, bool]] = {}
    for segment in segments:
        segment = segment.strip()
        if not segment:
            continue
        key, value = hole_split_pair(segment)
        result[key] = value
    return result

