class _Parser:
    # Grammar:
    #   expression := term (('+' | '-') term)*
    #   term       := unary (('*' | '/' | '%') unary)*
    #   unary      := '-' unary | power
    #   power      := primary ('^' unary)?        (right-associative)
    #   primary    := NUMBER | '(' expression ')'

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _match_op(self, ops):
        tok = self._peek()
        if tok is not None and tok[0] == "OP" and tok[1] in ops:
            self.pos += 1
            return tok[1]
        return None

    def parse_expression(self):
        value = self.parse_term()
        while True:
            op = self._match_op("+-")
            if op is None:
                break
            rhs = self.parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term(self):
        value = self.parse_unary()
        while True:
            op = self._match_op("*/%")
            if op is None:
                break
            rhs = self.parse_unary()
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
        return value

    def parse_unary(self):
        if self._match_op("-") is not None:
            return -self.parse_unary()
        return self.parse_power()

    def parse_power(self):
        base = self.parse_primary()
        if self._match_op("^") is not None:
            exp = self.parse_unary()
            return _c_pow(base, exp)
        return base

    def parse_primary(self):
        tok = self._peek()
        if tok is None:
            raise SyntaxError("Unexpected end of expression")
        if tok[0] == "NUM":
            self.pos += 1
            return tok[1]
        if tok[0] == "OP" and tok[1] == "(":
            self.pos += 1
            value = self.parse_expression()
            if self._match_op(")") is None:
                raise SyntaxError("Expected ')'")
            return value
        raise SyntaxError(f"Unexpected token: {tok[1]!r}")

