class _Parser:
    # Grammar:
    #   expr   := term (('+' | '-') term)*
    #   term   := unary (('*' | '/' | '%') unary)*
    #   unary  := '-' unary | power
    #   power  := atom ('^' unary)?        (right-associative)
    #   atom   := NUM | '(' expr ')'

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _peek_op(self):
        tok = self._peek()
        if tok is not None and tok[0] == "OP":
            return tok[1]
        return None

    def _advance(self):
        tok = self._peek()
        if tok is None:
            raise SyntaxError("unexpected end of expression")
        self.pos += 1
        return tok

    def parse(self):
        if not self.tokens:
            raise SyntaxError("empty expression")
        value = self._expr()
        if self.pos != len(self.tokens):
            raise SyntaxError(f"unexpected token at position {self.pos}")
        return value

    def _expr(self):
        value = self._term()
        while self._peek_op() in ("+", "-"):
            op = self._advance()[1]
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def _term(self):
        value = self._unary()
        while self._peek_op() in ("*", "/", "%"):
            op = self._advance()[1]
            rhs = self._unary()
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
        return value

    def _unary(self):
        if self._peek_op() == "-":
            self._advance()
            return -self._unary()
        return self._power()

    def _power(self):
        base = self._atom()
        if self._peek_op() == "^":
            self._advance()
            exp = self._unary()
            return _c_pow(base, exp)
        return base

    def _atom(self):
        tok = self._peek()
        if tok is None:
            raise SyntaxError("unexpected end of expression")
        if tok[0] == "NUM":
            self._advance()
            return tok[1]
        if tok == ("OP", "("):
            self._advance()
            value = self._expr()
            if self._peek() != ("OP", ")"):
                raise SyntaxError("expected ')'")
            self._advance()
            return value
        raise SyntaxError(f"unexpected token {tok[1]!r}")

def evaluate(expr):
    """
    Evaluate an integer arithmetic expression.

    Supports integer literals, + - * / % ^, unary minus, and parentheses.
    Division and modulo truncate toward zero (C-style), so the remainder
    takes the sign of the dividend. '^' is right-associative and binds
    tighter than unary minus, so -2^2 == -4.

    Raises SyntaxError for malformed input and ZeroDivisionError for
    division or modulo by zero.
    """

    # ---------- Tokenizer ----------
    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
            elif '0' <= c <= '9':
                start = i
                while i < n and '0' <= s[i] <= '9':
                    i += 1
                tokens.append(('NUM', int(s[start:i])))
            elif c in '+-*/%^':
                tokens.append(('OP', c))
                i += 1
            elif c == '(':
                tokens.append(('LPAREN', c))
                i += 1
            elif c == ')':
                tokens.append(('RPAREN', c))
                i += 1
            else:
                raise SyntaxError(f"Unexpected character {c!r} at position {i}")
        tokens.append(('END', None))
        return tokens

    # ---------- Integer arithmetic helpers ----------
    def c_div(a, b):
        if b == 0:
            raise ZeroDivisionError("division by zero")
        q = abs(a) // abs(b)
        return q if (a >= 0) == (b >= 0) else -q

    def c_mod(a, b):
        if b == 0:
            raise ZeroDivisionError("modulo by zero")
        return a - b * c_div(a, b)

    def c_pow(base, exp):
        if exp >= 0:
            return base ** exp
        # Negative exponent: only well-defined integers for these bases.
        if base == 1:
            return 1
        if base == -1:
            return 1 if exp % 2 == 0 else -1
        if base == 0:
            raise ZeroDivisionError("zero raised to a negative power")
        raise ValueError("negative exponent yields a non-integer result")

    # ---------- Recursive-descent parser ----------
    tokens = tokenize(expr)
    pos = 0

    def peek():
        return tokens[pos]

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def expect_end():
        if peek()[0] != 'END':
            raise SyntaxError(f"Unexpected token {peek()[1]!r}")

    # expr := term (('+' | '-') term)*
    def parse_expr():
        value = parse_term()
        while peek()[0] == 'OP' and peek()[1] in '+-':
            op = advance()[1]
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    # term := unary (('*' | '/' | '%') unary)*
    def parse_term():
        value = parse_unary()
        while peek()[0] == 'OP' and peek()[1] in '*/%':
            op = advance()[1]
            rhs = parse_unary()
            if op == '*':
                value = value * rhs
            elif op == '/':
                value = c_div(value, rhs)
            else:
                value = c_mod(value, rhs)
        return value

    # unary := '-' unary | power
    def parse_unary():
        if peek()[0] == 'OP' and peek()[1] == '-':
            advance()
            return -parse_unary()
        return parse_power()

    # power := atom ['^' unary]   (right-associative; exponent may be negated)
    def parse_power():
        base = parse_atom()
        if peek()[0] == 'OP' and peek()[1] == '^':
            advance()
            exp = parse_unary()
            return c_pow(base, exp)
        return base

    # atom := NUMBER | '(' expr ')'
    def parse_atom():
        kind, val = peek()
        if kind == 'NUM':
            advance()
            return val
        if kind == 'LPAREN':
            advance()
            value = parse_expr()
            if peek()[0] != 'RPAREN':
                raise SyntaxError("Expected ')'")
            advance()
            return value
        if kind == 'END':
            raise SyntaxError("Unexpected end of expression")
        raise SyntaxError(f"Unexpected token {val!r}")

    if tokens[0][0] == 'END':
        raise SyntaxError("Empty expression")

    result = parse_expr()
    expect_end()
    return result

