        if not self.tokens:
            raise SyntaxError('Empty expression')
        value = self._expr()
        if self.pos != len(self.tokens):
            raise SyntaxError(f'Unexpected token {self.tokens[self.pos][1]!r}')
        return value

    def _expr(self):
        value = self._term()
        while self._peek() in ('+', '-'):
            op = self._advance()[0]
            rhs = self._term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def _term(self):
        value = self._unary()
        while self._peek() in ('*', '/', '%'):
            op = self._advance()[0]
            rhs = self._unary()
            if op == '*':
                value = value * rhs
            elif op == '/':
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
        return value

    def _unary(self):
        if self._peek() == '-':
            self._advance()
            return -self._unary()
        return self._power()

