        base = self._atom()
        if self._peek() == '^':
            self._advance()
            exp = self._unary()
            return _int_pow(base, exp)
        return base

    def _atom(self):
        kind = self._peek()
        if kind == 'NUM':
            return self._advance()[1]
        if kind == '(':
            self._advance()
            value = self._expr()
            if self._peek() != ')':
                raise SyntaxError('Missing closing parenthesis')
            self._advance()
            return value
        if kind is None:
            raise SyntaxError('Unexpected end of expression')
        raise SyntaxError(f'Unexpected token {self.tokens[self.pos][1]!r}')

