    return -q if (a < 0) != (b < 0) else q

def _tmod(a, b):
    """C-style remainder: result takes the sign of the dividend."""
    if b == 0:
        raise ZeroDivisionError('modulo by zero')
    r = abs(a) % abs(b)
    return -r if a < 0 else r

