class _Parser:

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos][0]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind):
        if self.peek() != kind:
            raise SyntaxError(f'expected {kind!r}, got {self.peek()!r}')
        return self.advance()

    def parse_expr(self):
        value = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.advance()[0]
            rhs = self.parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term(self):
        value = self.parse_unary()
        while self.peek() in ('*', '/', '%'):
            op = self.advance()[0]
            rhs = self.parse_unary()
            if op == '*':
                value = value * rhs
            elif op == '/':
                value = _tdiv(value, rhs)
            else:
                value = _tmod(value, rhs)
        return value

    def parse_unary(self):
        if self.peek() == '-':
            self.advance()
            return -self.parse_unary()
        return self.parse_power()

    def parse_power(self):
        base = self.parse_primary()
        if self.peek() == '^':
            self.advance()
            exp = self.parse_unary()
            return _tpow(base, exp)
        return base

    def parse_primary(self):
        kind = self.peek()
        if kind == 'NUM':
            return self.advance()[1]
        if kind == '(':
            self.advance()
            value = self.parse_expr()
            self.expect(')')
            return value
        raise SyntaxError(f'unexpected token {kind!r}')

def evaluate(expr):
    """Evaluate an integer arithmetic expression.

    Supports + - * / % ^, unary minus, and parentheses. Division and
    modulo truncate toward zero (C semantics). Raises SyntaxError for
    malformed input and ZeroDivisionError for division by zero.
    """
    if not isinstance(expr, str):
        raise SyntaxError('expression must be a string')
    tokens = _tokenize(expr)
    if tokens[0][0] == 'EOF':
        raise SyntaxError('empty expression')
    parser = _Parser(tokens)
    value = parser.parse_expr()
    if parser.peek() != 'EOF':
        raise SyntaxError(f'unexpected token {parser.peek()!r} at end of expression')
    return value

