from typing import Dict, List, Optional, Union

ACCEPTED_COINS = (5, 10, 25)


class VendingMachine:
    def __init__(self, prices: Dict[str, int], coins: Dict[int, int]):
        self.prices: Dict[str, int] = dict(prices)
        self.coins: Dict[int, int] = {d: c for d, c in coins.items() if c > 0}
        self.inserted: List[int] = []

    def insert(self, coin: int) -> bool:
        if coin not in ACCEPTED_COINS:
            return False
        self.inserted.append(coin)
        return True

    def balance(self) -> int:
        return sum(self.inserted)

    def select(self, item: str) -> Union[List[int], str]:
        if item not in self.prices:
            return 'UNKNOWN'

        price = self.prices[item]
        bal = self.balance()
        if bal < price:
            return 'INSUFFICIENT'

        # Inserted coins become part of the pool available for change.
        pool: Dict[int, int] = dict(self.coins)
        for coin in self.inserted:
            pool[coin] = pool.get(coin, 0) + 1

        change = self._make_change(bal - price, pool)
        if change is None:
            return 'NO_CHANGE'

        for coin in change:
            pool[coin] -= 1
        self.coins = {d: c for d, c in pool.items() if c > 0}
        self.inserted = []
        return change

    def cancel(self) -> List[int]:
        returned = list(self.inserted)
        self.inserted = []
        return returned

    @staticmethod
    def _make_change(amount: int, pool: Dict[int, int]) -> Optional[List[int]]:
        """Return the fewest coins from pool summing to amount, or None if impossible."""
        if amount == 0:
            return []

        denoms = sorted(d for d, c in pool.items() if c > 0 and d > 0)
        INF = float('inf')
        best = [INF] * (amount + 1)
        best[0] = 0
        picks: List[List[int]] = []

        # Bounded knapsack over denominations: best[a] = min coins to make a.
        for d in denoms:
            count = pool[d]
            new_best = [INF] * (amount + 1)
            pick = [0] * (amount + 1)
            for a in range(amount + 1):
                for j in range(min(count, a // d) + 1):
                    candidate = best[a - j * d] + j
                    if candidate < new_best[a]:
                        new_best[a] = candidate
                        pick[a] = j
            picks.append(pick)
            best = new_best

        if best[amount] == INF:
            return None

        # Reconstruct the chosen coins by walking the stages backwards.
        result: List[int] = []
        a = amount
        for idx in range(len(denoms) - 1, -1, -1):
            d = denoms[idx]
            j = picks[idx][a]
            result.extend([d] * j)
            a -= j * d

        return sorted(result, reverse=True)

from collections import Counter

ACCEPTED_COINS = (5, 10, 25)


class VendingMachine:
    def __init__(self, prices, coins):
        self._prices = dict(prices)
        self._inventory = Counter({c: n for c, n in dict(coins).items() if n > 0})
        self._inserted = []

    def insert(self, coin):
        if coin not in ACCEPTED_COINS:
            return False
        self._inserted.append(coin)
        return True

    def balance(self):
        return sum(self._inserted)

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'

        price = self._prices[item]
        bal = self.balance()
        if bal < price:
            return 'INSUFFICIENT'

        change_due = bal - price
        pool = Counter(self._inventory)
        pool.update(self._inserted)

        change = self._make_change(change_due, pool)
        if change is None:
            return 'NO_CHANGE'

        pool.subtract(Counter(change))
        self._inventory = Counter({c: n for c, n in pool.items() if n > 0})
        self._inserted = []
        return change

    def cancel(self):
        returned = list(self._inserted)
        self._inserted = []
        return returned

    @staticmethod
    def _make_change(amount, inventory):
        # best maps reachable total -> (coin_count, tuple_of_coins), minimal count
        best = {0: (0, ())}
        for denom, n in inventory.items():
            if n <= 0:
                continue
            new = dict(best)
            for total, (count, coins) in best.items():
                for k in range(1, n + 1):
                    t = total + k * denom
                    if t > amount:
                        break
                    cand = (count + k, coins + (denom,) * k)
                    if t not in new or cand[0] < new[t][0]:
                        new[t] = cand
            best = new

        if amount not in best:
            return None
        return sorted(best[amount][1], reverse=True)

