        # Next booking starts at or after `start`; overlaps if it starts before `end`.
        if idx < len(self._bookings) and self._bookings[idx][0] < end:
            return False
        # Previous booking starts before `start`; overlaps if it ends after `start`.
        if idx > 0 and self._bookings[idx - 1][1] > start:
            return False

        self._bookings.insert(idx, (start, end))
        return True

    def cancel(self, start, end):
        """Cancel the exact booking [start, end). Returns False if no such booking exists."""
        self._validate(start, end)
        idx = bisect.bisect_left(self._bookings, (start, end))
        if idx < len(self._bookings) and self._bookings[idx] == (start, end):
            del self._bookings[idx]
            return True
        return False

