        """Return free gaps (start, end) within the window [lo, hi) of length >= min_len."""
        if lo > hi:
            raise ValueError(f"invalid window: lo ({lo}) must be <= hi ({hi})")

        gaps = []
        cursor = lo
        for s, e in self._bookings:
            if e <= lo or s >= hi:
                continue  # booking lies outside the window
            s = max(s, lo)
            gap_len = s - cursor
            if gap_len > 0 and gap_len >= min_len:
                gaps.append((cursor, s))
            cursor = max(cursor, min(e, hi))

        tail_len = hi - cursor
        if tail_len > 0 and tail_len >= min_len:
            gaps.append((cursor, hi))
        return gaps

from typing import Any, Callable, List, Optional, Tuple
Parser = Callable[[str, int], Optional[Tuple[Any, int]]]

class ParseError(Exception):

    def __init__(self, message: str, pos: int) -> None:
        super().__init__(f'{message} at position {pos}')
        self.message = message
        self.pos = pos

def hole_many_empty_values(value: Any) -> List[Any]:
    """Called by many() when the inner parser succeeds WITHOUT consuming input.

    Receives the value the inner parser produced. Must return the list of
    values that many() should append to its result before it stops looping.
    The return value must be a list (it may be empty). many() stops looping
    after this call regardless of what is returned.
    """
    raise NotImplementedError

def hole_map_apply(f: Callable[..., Any], value: Any) -> Any:
    """Called by map_() after the inner parser succeeds.

    Receives the callable f and the value produced by the inner parser.
    Must return the value that map_() produces as its parsed result. f must
    be called exactly once. The calling convention (how `value` is passed to
    f, including for seq() results, which are lists) is the decision to make.
    """
    raise NotImplementedError

def satisfy(pred: Callable[[str], bool]) -> Parser:

    def p(s: str, i: int) -> Optional[Tuple[Any, int]]:
        if i < len(s) and pred(s[i]):
            return (s[i], i + 1)
        return None
    return p

def char(c: str) -> Parser:
    if len(c) != 1:
        raise ValueError('char() expects a single character')
    return satisfy(lambda ch: ch == c)

def string(t: str) -> Parser:

    def p(s: str, i: int) -> Optional[Tuple[Any, int]]:
        if s.startswith(t, i):
            return (t, i + len(t))
        return None
    return p

def seq(*parsers: Parser) -> Parser:

    def p(s: str, i: int) -> Optional[Tuple[Any, int]]:
        values: List[Any] = []
        for q in parsers:
            r = q(s, i)
            if r is None:
                return None
            v, i = r
            values.append(v)
        return (values, i)
    return p

def alt(*parsers: Parser) -> Parser:

    def p(s: str, i: int) -> Optional[Tuple[Any, int]]:
        for q in parsers:
            r = q(s, i)
            if r is not None:
                return r
        return None
    return p

def many(parser: Parser) -> Parser:

    def p(s: str, i: int) -> Optional[Tuple[Any, int]]:
        values: List[Any] = []
        while True:
            r = parser(s, i)
            if r is None:
                break
            v, new_i = r
            if new_i == i:
                values.extend(hole_many_empty_values(v))
                break
            values.append(v)
            i = new_i
        return (values, i)
    return p

def sep_by(parser: Parser, sep: Parser) -> Parser:

    def p(s: str, i: int) -> Optional[Tuple[Any, int]]:
        items: List[Any] = []
        r = parser(s, i)
        if r is None:
            return ([], i)
        v, i = r
        items.append(v)
        while True:
            sr = sep(s, i)
            if sr is None:
                break
            pr = parser(s, sr[1])
            if pr is None:
                break
            v, i = pr
            items.append(v)
        return (items, i)
    return p

def map_(f: Callable[..., Any], parser: Parser) -> Parser:

    def p(s: str, i: int) -> Optional[Tuple[Any, int]]:
        r = parser(s, i)
        if r is None:
            return None
        v, new_i = r
        return (hole_map_apply(f, v), new_i)
    return p

def parse(p: Parser, s: str) -> Any:
    r = p(s, 0)
    if r is None:
        raise ParseError('parse failed', 0)
    value, i = r
    if i != len(s):
        raise ParseError('unexpected input', i)
    return value

def check_invariants() -> None:
    assert parse(char('a'), 'a') == 'a'
    assert parse(string('abc'), 'abc') == 'abc'
    assert char('a')('b', 0) is None
    assert many(string(''))('y', 0) == ([], 0)
    assert parse(many(char('x')), 'xxx') == ['x', 'x', 'x']
    assert parse(sep_by(char('a'), char(',')), 'a,a,a') == ['a', 'a', 'a']
    assert parse(sep_by(char('a'), char(',')), '') == []
    assert parse(map_(str.upper, char('a')), 'a') == 'A'


