import inspect

from typing import Any, Callable, List

def _accepts_n_positional(f: Callable[..., Any], n: int) -> bool:
    try:
        sig = inspect.signature(f)
    except (TypeError, ValueError):
        return False
    params = list(sig.parameters.values())
    if any((p.kind == p.VAR_POSITIONAL for p in params)):
        return True
    positional = [p for p in params if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)]
    required = [p for p in positional if p.default is p.empty]
    return len(required) <= n <= len(positional)

def hole_many_empty_values(value: Any) -> List[Any]:
    return []

def hole_map_apply(f: Callable[..., Any], value: Any) -> Any:
    if isinstance(value, list) and len(value) >= 2 and _accepts_n_positional(f, len(value)):
        return f(*value)
    return f(value)

def color_graph(nodes, edges, k, precolored=None):
    adj = {}

    def add_vertex(v):
        if v not in adj:
            adj[v] = set()

    for v in nodes:
        add_vertex(v)

    for u, v in edges:
        if u == v:
            return None  # self-loop can never be properly colored
        add_vertex(u)
        add_vertex(v)
        adj[u].add(v)
        adj[v].add(u)

    precolored = dict(precolored) if precolored else {}
    for v, c in precolored.items():
        if not isinstance(c, int) or isinstance(c, bool) or c < 0 or c >= k:
            return None
        add_vertex(v)

    if not adj:
        return {}
    if k <= 0:
        return None

    # Precolored neighbors must not share a color.
    for v, c in precolored.items():
        for u in adj[v]:
            if u in precolored and precolored[u] == c:
