    nodes receive different colors, keeping any precolored nodes fixed.
    Return None if no such coloring exists.
    """
    adj = defaultdict(set)
    all_nodes = set(nodes)

    for u, v in edges:
        all_nodes.add(u)
        all_nodes.add(v)
        if u == v:
            return None  # a self-loop can never be properly colored
        adj[u].add(v)
        adj[v].add(u)

    fixed = dict(precolored or {})
    for n in fixed:
        all_nodes.add(n)

    if not all_nodes:
        return {}
    if k <= 0:
        return None

    for n, c in fixed.items():
        if not isinstance(c, int) or c < 0 or c >= k:
            return None
    for n, c in fixed.items():
        for m in adj[n]:
            if m in fixed and fixed[m] == c:
                return None

    colors = {}
    domains = {n: set(range(k)) for n in all_nodes}

    def assign(n, c, removed):
        """Fix n to color c and prune c from uncolored neighbors' domains.
        Records pruned (node, color) pairs in `removed`. Returns False if
        some uncolored neighbor's domain becomes empty."""
        colors[n] = c
        ok = True
        for m in adj[n]:
            if m not in colors and c in domains[m]:
                domains[m].discard(c)
                removed.append((m, c))
                if not domains[m]:
                    ok = False
        return ok

    def unassign(n, removed):
        del colors[n]
        for m, c in removed:
            domains[m].add(c)

    # Apply precolored nodes first (propagating their constraints).
    for n, c in fixed.items():
        removed = []
        if not assign(n, c, removed):
            return None

    def search():
        uncolored = [n for n in all_nodes if n not in colors]
        if not uncolored:
            return True
        # Most constrained variable first; break ties by highest degree.
        n = min(uncolored, key=lambda x: (len(domains[x]), -len(adj[x]), str(x)))
        for c in sorted(domains[n]):
            removed = []
            if assign(n, c, removed) and search():
                return True
            unassign(n, removed)
        return False

    if search():
        return dict(colors)
    return None

import re


def wrap_text(text, width):
    """Greedily word-wrap text to the given width.

    Paragraphs are separated by one or more blank lines (lines containing
    only whitespace). Each paragraph is wrapped independently, and the
    wrapped paragraphs are joined with a single blank line. Words longer
    than width are split into chunks of at most width characters.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    wrapped_paragraphs = []
    for paragraph in re.split(r"\n\s*\n", text):
        words = paragraph.split()
        if not words:
            continue

        lines = []
        current = ""
        for word in words:
            if len(word) > width:
                if current:
                    lines.append(current)
                    current = ""
                pieces = [word[i:i + width] for i in range(0, len(word), width)]
                lines.extend(pieces[:-1])
                current = pieces[-1]
            elif not current:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word

        if current:
            lines.append(current)

        wrapped_paragraphs.append("\n".join(lines))

    return "\n\n".join(wrapped_paragraphs)

