        for word in words:
            # Break words longer than the width across lines
            while len(word) > width:
                if current:
                    lines.append(current)
                    current = ""
                lines.append(word[:width])
                word = word[width:]
            if not current:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word
        if current or not lines:
            lines.append(current)
        return lines

    paragraphs = []
    current_para = []
    for line in text.split("\n"):
        if line.strip():
            current_para.extend(line.split())
        else:
            if current_para:
                paragraphs.append(current_para)
                current_para = []
            paragraphs.append(None)  # marker for blank line separator
    if current_para:
        paragraphs.append(current_para)

    result = []
    for para in paragraphs:
        if para is None:
            result.append("")
        else:
            result.extend(wrap_paragraph(para, width))

    # Collapse any consecutive or leading/trailing blank markers into single separators
    cleaned = []
    for line in result:
        if line == "" and (not cleaned or cleaned[-1] == ""):
            continue
        cleaned.append(line)
    while cleaned and cleaned[-1] == "":
        cleaned.pop()
    while cleaned and cleaned[0] == "":
        cleaned.pop(0)

    return "\n".join(cleaned)

