import functools
import re

_SEMVER_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-((?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)"
    r"(?:\.(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


def _parse(version):
    if not isinstance(version, str):
        raise ValueError(f"Invalid semantic version (not a string): {version!r}")
    match = _SEMVER_RE.fullmatch(version)
    if match is None:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    pre = match.group(4)
    prerelease = tuple(pre.split(".")) if pre else ()
    # Build metadata (group 5) is ignored for precedence.
    return major, minor, patch, prerelease


def _sign(x, y):
    if x < y:
        return -1
    if x > y:
        return 1
    return 0


def _compare_prerelease(pa, pb):
    if pa == pb:
        return 0
    # A version without pre-release fields has higher precedence.
    if not pa:
        return 1
    if not pb:
        return -1
    for x, y in zip(pa, pb):
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            result = _sign(int(x), int(y))
        elif x_num:
            # Numeric identifiers have lower precedence than alphanumeric ones.
            result = -1
        elif y_num:
            result = 1
        else:
            # ASCII lexical comparison.
            result = _sign(x, y)
        if result != 0:
            return result
    # A larger set of pre-release fields has higher precedence when all
    # preceding identifiers are equal.
    return _sign(len(pa), len(pb))


def compare_versions(a, b):
    """Compare two semantic versions per SemVer 2.0.0 precedence.

    Returns -1 if a < b, 0 if a == b (precedence-wise), 1 if a > b.
    Build metadata is ignored. Raises ValueError for invalid versions.
    """
    pa = _parse(a)
    pb = _parse(b)
    for x, y in zip(pa[:3], pb[:3]):
        result = _sign(x, y)
        if result != 0:
            return result
    return _compare_prerelease(pa[3], pb[3])


def sort_versions(versions):
    """Return a new list of version strings sorted in ascending SemVer precedence.

    Raises ValueError if any version is invalid.
    """
    versions = list(versions)
    for v in versions:
        _parse(v)  # validate all inputs up front
    return sorted(versions, key=functools.cmp_to_key(compare_versions))

import re
from functools import cmp_to_key

_SEMVER_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-((?:0|[1-9][0-9]*|[0-9]*[a-zA-Z-][0-9a-zA-Z-]*)"
    r"(?:\.(?:0|[1-9][0-9]*|[0-9]*[a-zA-Z-][0-9a-zA-Z-]*))*))?"
    r"(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?"
)


def _parse(version):
    """Parse a SemVer 2.0.0 string into (major, minor, patch, prerelease_ids).

    prerelease_ids is a tuple of identifier strings, or None for a release version.
    Build metadata is validated but otherwise ignored for precedence.
    Raises ValueError for invalid input.
    """
    if not isinstance(version, str):
        raise ValueError(f"Invalid semantic version (not a string): {version!r}")
    match = _SEMVER_RE.fullmatch(version)
    if match is None:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major, minor, patch, pre, _build = match.groups()
    pre_ids = tuple(pre.split(".")) if pre is not None else None
    return int(major), int(minor), int(patch), pre_ids


def _is_numeric(identifier):
    return identifier.isdigit()


def _compare_prerelease(a, b):
    """Compare two prerelease identifier tuples (or None for release)."""
    if a is None and b is None:
        return 0
    if a is None:
        return 1  # release has higher precedence than any prerelease
    if b is None:
        return -1

    for x, y in zip(a, b):
        x_num, y_num = _is_numeric(x), _is_numeric(y)
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num:
            return -1  # numeric identifiers have lower precedence than alphanumeric
        elif y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1

    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def compare_versions(a, b):
    """Compare two semantic version strings by SemVer 2.0.0 precedence.

    Returns -1 if a < b, 0 if a == b, 1 if a > b.
    Build metadata is ignored for precedence.
    Raises ValueError if either version is invalid.
    """
    major_a, minor_a, patch_a, pre_a = _parse(a)
    major_b, minor_b, patch_b, pre_b = _parse(b)

    for x, y in ((major_a, major_b), (minor_a, minor_b), (patch_a, patch_b)):
        if x != y:
            return -1 if x < y else 1

    return _compare_prerelease(pre_a, pre_b)


def sort_versions(versions):
    """Return a new list of version strings sorted in ascending SemVer precedence.

    Versions that compare equal (e.g. differing only in build metadata)
    keep their original relative order.
    Raises ValueError if any version is invalid.
    """
    versions = list(versions)
    for v in versions:
        _parse(v)  # validate all entries up front
    return sorted(versions, key=cmp_to_key(compare_versions))

